/*
 * A309884  Numbers k such that A003132(k^3) = A003132(k), where A003132(n) is
 *          the sum of the squares of the digits of n.
 * https://oeis.org/A309884
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 7, u64 n <= 41, u128 n <= 41,
 *            big any n
 * Helpers:   big_pow, get_digits
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Generated by exhaustive search for k such that
    sum_of_squares_of_digits(k^3) == sum_of_squares_of_digits(k)
    Sequence A309884: numbers k with the above property.  */

#include <stdlib.h>
#include <stddef.h>
#include <stdint.h>
#include "../utils/get_digits.h"
#include "../utils/big_pow.h"

/* Helper: sum of squares of the decimal digits of x.  */
static seq_t sum_square_digits(seq_t x)
{
    /* 8192 digits is enough for the first 10 000 terms. */
    uint8_t buf[8192];
    size_t len = 0;
    get_digits(x, buf, &len);

    seq_t sum = 0;
    for (size_t i = 0; i < len; ++i)
        sum += (seq_t)(buf[i] * buf[i]);

    return sum;
}

seq_t a(idx_t n)
{
    /* Static storage for memoization */
    static seq_t *table   = NULL;  /* array of found terms         */
    static size_t  cap    = 0;     /* allocated capacity in items  */
    static idx_t   count  = 0;     /* number of terms stored       */
    static idx_t   last_k = 0;     /* last integer examined        */

    /* Ensure we have at least n terms in the table. */
    while (count < n) {
        seq_t k   = (seq_t)last_k;
        seq_t s1  = sum_square_digits(k);

        /* Compute k^3 using big_pow (seq_t base, seq_t exp). */
        seq_t k3  = big_pow(k, (seq_t)3);
        seq_t s2  = sum_square_digits(k3);

        if (s1 == s2) {
            /* Grow the array if necessary. */
            if (count >= cap) {
                size_t new_cap = (cap == 0) ? 16 : cap * 2;
                seq_t *tmp = (seq_t *)realloc(table, new_cap * sizeof(seq_t));
                if (!tmp) abort();          /* out of memory */
                table = tmp;
                cap   = new_cap;
            }
            table[count++] = k;           /* store the term */
        }
        ++last_k;
    }

    return table[n - 1];
}
